// BITE NIGHT finishing moves, written as timelines. Each script is a pure list of timed stage
// directions on a director object `c` (poses, moves, props, camera cuts, lights, stamps, sounds);
// the 3D scene implements the director, the tests run the scripts against a recorder, and the
// chat replay viewer re-stages a posted finisher from the same script. No imports, no rendering.
//
// Stage coordinates are local to the finish: the winner stands at x = -1.1 facing +x, the loser
// at x = +1.1 facing them; y is up, z is toward the camera. The scene mirrors x when the winner
// is on the right. Times are seconds. Cartoon mayhem only: nobody is ever really hurt.
const W='w',L='l';
const SHOT={two:[[0,1.5,5.6],[0,1.15,0]],wide:[[0,2.4,9.2],[0,1.5,0]],w:[[-.15,1.5,2.9],[-1.1,1.25,0]],l:[[.15,1.5,2.9],[1.1,1.2,0]],lowW:[[-.2,.3,2.5],[-1.1,1.5,0]],lowL:[[.2,.3,2.5],[1.1,1.5,0]],top:[[0,8.5,3.2],[0,0,0]],up:[[1.1,.5,3.8],[1.1,7,0]],far:[[0,3.4,14],[0,3,0]]};
const cut=(c,t,name,fov)=>c.cam(t,SHOT[name][0],SHOT[name][1],fov);
const push=(c,t0,t1,name)=>c.dolly(t0,t1,SHOT[name][0],SHOT[name][1]);
const open=c=>{cut(c,0,'two');c.light(0,.5);c.pose(0,L,'dizzy');c.pose(0,W,'taunt');c.snd(0,'sting');};
const STAMP={curtain:'CURTAIN CALL!',dive:'STAGE DIVE!',rub:'BELLY RUB!'};
const close=(c,t,name,kind='curtain',pose='cheer')=>{c.pose(t,W,pose);c.stamp(t,STAMP[kind],name);c.snd(t,'stamp');c.light(t,.9);};
// The loser, already heading skyward, leaves the atmosphere and becomes a star.
const orbit=(c,t,x=1.1)=>{c.sky(t,'space');c.cam(t,[x,60,14],[x,63,0],38);c.place(t,L,[x-4,60,0]);c.pose(t,L,'fly');c.move(t,t+1.3,L,[x+2,66,-26]);c.spin(t,t+1.3,L,'x',3);c.grow(t,t+1.3,L,.06);c.snd(t,'whoosh');c.prop(t+1.3,'star',[x+2,66,-26],{s:1.4});c.snd(t+1.3,'ding');c.flash(t+1.3,0xffffff,.45);c.sky(t+2.1,'stage');c.vis(t+2.1,L,false);};

